package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Domain 0: සිතියම් කියවීම, පරිමාණ හා භූගෝලීය තොරතුරු
 * (Topographic Maps, Scales, Contours, Grid References, GIS, GPS & Remote Sensing)
 * Strictly unique, non-repetitive MCQs with 4 authentic Sinhala options each.
 */
internal object GeographyLiveExamMapsBank {

  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun mapQuestions(): List<QSpec> {
    val t = "සිතියම් කියවීම, පරිමාණ හා භූගෝලීය තොරතුරු"
    return listOf(
      q(t, "ශ්‍රී ලංකාවේ මිනින්දෝරු දෙපාර්තමේන්තුව මඟින් ප්‍රකාශයට පත් කරන සම්මත භූලක්ෂණ සිතියම් මාලාවේ පරිමාණය කුමක්ද?",
        "1:50,000 (මෙට්‍රික් මාලාව)", "1:10,000", "1:500,000", "1:1,000,000",
        "පැරණි අඟල් 1 සැතපුම් (1:63,360) සිතියම් වෙනුවට වර්තමානයේ 1:50,000 මෙට්‍රික් සිතියම් භාවිත කෙරේ."),
      q(t, "1:50,000 භූලක්ෂණ සිතියමක සෙ.මී. 1 කින් නිරූපණය වන සැබෑ භූමි දුර කොපමණද?",
        "මීටර් 500 (කි.මී. 0.5)", "මීටර් 50", "කිලෝමීටර් 5", "මීටර් 250",
        "1:50,000 යනු සිතියමේ 1 cm = බිමෙහි 50,000 cm = 500 m = 0.5 km යන්නයි."),
      q(t, "ශ්‍රී ලංකාවේ මුළු භූමි ප්‍රමාණය ආවරණය කිරීම සඳහා සකස් කර ඇති 1:50,000 භූලක්ෂණ සිතියම් පත්‍ර සංඛ්‍යාව කීයද?",
        "සිතියම් පත්‍ර 92 කි", "සිතියම් පත්‍ර 25 කි", "සිතියම් පත්‍ර 50 කි", "සිතියම් පත්‍ර 150 කි",
        "දිවයින පුරා 1:50,000 මෙට්‍රික් භූලක්ෂණ සිතියම් පත්‍ර 92 ක් මිනින්දෝරු දෙපාර්තමේන්තුව විසින් ප්‍රකාශයට පත් කර ඇත."),
      q(t, "පැරණි ශ්‍රී ලංකා අඟල් එකේ භූලක්ෂණ සිතියම්වල (One-Inch Maps) නිරූපණ භාග පරිමාණය කුමක්ද?",
        "1:63,360", "1:50,000", "1:25,000", "1:100,000",
        "සැතපුම් 1 ක් අඟල් 63,360 ක් වන බැවින් අඟලට සැතපුම පරිමාණය 1:63,360 ලෙස දැක්වේ."),
      q(t, "'1:25,000' ලෙස දැක්වෙන පරිමාණ ප්‍රකාශන ක්‍රමය සිතියම් විද්‍යාවේදී හඳුන්වන්නේ කුමන නමින්ද?",
        "නිරූපණ භාගය (Representative Fraction / RF)", "ප්‍රකාශිත පරිමාණය (Statement Scale)", "රේඛීය පරිමාණය (Linear Scale)", "සංසන්දනාත්මක පරිමාණය",
        "ඕනෑම මිනුම් ඒකකයකින් කියවිය හැකි අනුපාත ආකාරය නිරූපණ භාගය (RF) නම් වේ."),
      q(t, "සිතියමක් ඡායාපිටපත් කිරීමේදී හෝ විශාලනය/කුඩා කිරීමේදී පවා නිවැරදි මිනුම් ලබා ගැනීමට වඩාත් උචිත පරිමාණ වර්ගය කුමක්ද?",
        "රේඛීය පරිමාණය (Linear / Bar Scale)", "ප්‍රකාශිත පරිමාණය", "නිරූපණ භාගය පමණි", "වාචික පරිමාණය",
        "රේඛීය පරිමාණය සිතියම සමඟ සමානුපාතිකව විශාල හෝ කුඩා වන බැවින් මිනුම් වරදින්නේ නැත."),
      q(t, "'සෙ.මී. 2 ට කි.මී. 1 කි' යන ප්‍රකාශිත පරිමාණයේ නිරූපණ භාගය (RF) කුමක්ද?",
        "1:50,000", "1:20,000", "1:100,000", "1:200,000",
        "2 cm = 1 km = 100,000 cm බැවින් 1 cm = 50,000 cm හෙවත් 1:50,000 වේ."),
      q(t, "1:10,000 සහ 1:1,000,000 යන සිතියම් දෙක සැසඳීමේදී 'විශාල පරිමාණ සිතියම' (Large Scale Map) කුමක්ද?",
        "1:10,000 සිතියම", "1:1,000,000 සිතියම", "දෙකම සමාන වේ", "පරිමාණය මත තීරණය කළ නොහැක",
        "භාගයක හරය කුඩා වන තරමට පරිමාණය විශාල වන අතර කුඩා ප්‍රදේශයක වැඩි විස්තර පෙන්වයි."),
      q(t, "නගර සැලසුමක් හෝ ගොඩනැගිලි භූමි සැලැස්මක් ඇඳීම සඳහා වඩාත් සුදුසු වන්නේ කුමන ආකාරයේ සිතියමක්ද?",
        "විශාල පරිමාණ සිතියම් (Large-scale plans)", "කුඩා පරිමාණ ලෝක සිතියම්", "සිතියම් පොත් සිතියම් (Atlas maps)", "දේශගුණ කලාප සිතියම්",
        "විශාල පරිමාණ සිතියම් මඟින් කුඩා ප්‍රදේශයක මංමාවත්, ගොඩනැගිලි ආදී සියුම් තොරතුරු දැක්වේ."),
      q(t, "ශ්‍රී ලංකාවේ 1:50,000 භූලක්ෂණ සිතියමක සම්මත සමෝච්ච රේඛා පරතරය (Contour Interval) මීටර් කීයද?",
        "මීටර් 20 කි", "මීටර් 5 කි", "මීටර් 100 කි", "මීටර් 50 කි",
        "ශ්‍රී ලංකාවේ 1:50,000 සිතියම්වල සමෝච්ච රේඛා මීටර් 20 පරතරයෙන් අඳිනු ලැබේ."),
      q(t, "භූලක්ෂණ සිතියමක ජලාශ, ගංගා, ඇළ දොළ සහ කලපු නිරූපණය කිරීමට භාවිත කරන සම්මත වර්ණය කුමක්ද?",
        "නිල් පැහැය", "දුඹුරු පැහැය", "කොළ පැහැය", "කළු පැහැය",
        "ජල වහන ලක්ෂණ (Drainage features) සැමවිටම නිල් පැහැයෙන් දක්වයි."),
      q(t, "සම්මත භූලක්ෂණ සිතියම්වල සමෝච්ච රේඛා සහ උන්නතාංශ අගයන් දැක්වීමට යොදන වර්ණය කුමක්ද?",
        "දුඹුරු පැහැය", "රතු පැහැය", "නිල් පැහැය", "කහ පැහැය",
        "භූ විෂමතාව හා සමෝච්ච රේඛා දැක්වීම සඳහා දුඹුරු වර්ණය යොදා ගැනේ."),
      q(t, "භූලක්ෂණ සිතියමක ස්වාභාවික වනාන්තර, කඩොලාන හා වගාබිම් දැක්වීමට යොදාගන්නා ප්‍රධාන වර්ණය කුමක්ද?",
        "කොළ පැහැය", "දුඹුරු පැහැය", "දම් පැහැය", "කළු පැහැය",
        "වෘක්ෂලතා හා කෘෂිකාර්මික ඉඩම් කොළ පැහැති සංකේත මඟින් නිරූපණය කෙරේ."),
      q(t, "සිතියමක ප්‍රධාන මහාමාර්ග (A ශ්‍රේණියේ මාර්ග) සහ නාගරික මාර්ග දැක්වීමට බහුලව භාවිත කරන වර්ණය කුමක්ද?",
        "රතු පැහැය", "නිල් පැහැය", "කොළ පැහැය", "අළු පැහැය",
        "ප්‍රධාන ප්‍රවාහන මාර්ග රතු වර්ණයෙන් ද දුම්රිය මාර්ග කළු වර්ණයෙන් ද දැක්වේ."),
      q(t, "භූලක්ෂණ සිතියමක පිහිටීමක් ඉතා නිවැරදිව මීටර් 100 ක් ඇතුළත හඳුනා ගැනීම සඳහා භාවිත කරන ඛණ්ඩාංක ක්‍රමය කුමක්ද?",
        "අංක 6 ඛණ්ඩාංකය (6-figure grid reference)", "අංක 4 ඛණ්ඩාංකය", "අංක 2 ඛණ්ඩාංකය", "විශාලන පරිමාණය",
        "අංක 6 ඛණ්ඩාංකය මඟින් කි.මී. 1x1 කොටුව 100m x 100m කුඩා කොටු 100 කට බෙදා නිශ්චිත ස්ථානය දක්වයි."),
      q(t, "සිතියම් ඛණ්ඩාංකයක් (Grid Reference) කියවීමේදී පළමුවෙන්ම කියවිය යුත්තේ කුමන රේඛා අගයද?",
        "නැගෙනහිර රේඛා අගය (Eastings)", "උතුරු රේඛා අගය (Northings)", "සමෝච්ච රේඛා අගය", "දේශාංශ අගය",
        "ඛණ්ඩාංක කියවීමේ මූලික රීතිය 'පළමුව Eastings (සිරස් රේඛා), දෙවනුව Northings (තිරස් රේඛා)' යන්නයි."),
      q(t, "සමෝච්ච රේඛා පහළ බිම දෙසට නෙරා යන 'U' හෝ 'V' හැඩැති ආරුක්කුවක් ලෙස පිහිටීමෙන් දැක්වෙන භූ ලක්ෂණය කුමක්ද?",
        "නෙරුව / කඳු වැටි අග්‍රය (Spur)", "නිම්නය (Valley)", "කඳු ගැටය (Knoll)", "වගුරු බිම",
        "V අකුරේ තුඩ පහළ උන්නතාංශය දෙසට යොමු වූ විට කඳු නෙරුවක් (Spur) ද, ඉහළට යොමු වූ විට නිම්නයක් ද දැක්වේ."),
      q(t, "සමෝච්ච රේඛා ඉහළ උන්නතාංශ දෙසට 'V' හැඩයෙන් නැමී තිබෙන තැන්හි බොහෝ විට ගලා බසින ලක්ෂණය කුමක්ද?",
        "ගංගාවක් හෝ දොළ පහරක් (නිම්නයක් තුළින්)", "ප්‍රපාතාකාර කඳු මුදුනක්", "කලපුවක්", "ගල් ගුහාවක්",
        "ඉහළ උන්නතාංශ දෙසට නැමුණු V රේඛා මඟින් ගංගා නිම්න නිරූපණය කෙරේ."),
      q(t, "ඉහළ හිස කොටසේ සමෝච්ච රේඛා ඉතා සමීපව පිහිටා, පහළ කොටසේ රේඛා ඈතින් පිහිටා ඇති බෑවුම කුමන ආකාරයේ බෑවුමක්ද?",
        "අවතල බෑවුම (Concave Slope)", "උත්තල බෑවුම (Convex Slope)", "ඒකාකාර බෑවුම (Uniform Slope)", "සෝපාන බෑවුම",
        "ඉහළ තද බෑවුමක් (ළං වූ රේඛා) හා පහළ මෘදු බෑවුමක් (ඈත් වූ රේඛා) ඇති විට අවතල බෑවුමක් සෑදේ."),
      q(t, "ඉහළ කොටසේ සමෝච්ච රේඛා ඈතින් පිහිටා පහළට යත්ම ඉතා ළං වී පිහිටන්නේ නම් එම බෑවුම කුමක්ද?",
        "උත්තල බෑවුම (Convex Slope)", "අවතල බෑවුම (Concave Slope)", "සමතලා තැනිතලාව", "ප්‍රපාතය",
        "උත්තල බෑවුමේදී මුදුන මෘදු වී පාමුල තීව්‍ර වන අතර අන්තර් දර්ශනය (Intervisibility) බාධා විය හැකිය."),
      q(t, "සමෝච්ච රේඛා එකිනෙක මත ගොඩගැසී තනි රේඛාවක් මෙන් දිස්වන සිතියම් ස්ථානයකින් පෙනෙන භූ ලක්ෂණය කුමක්ද?",
        "සිරස් ප්‍රපාතය හෝ දිය ඇල්ල (Cliff / Waterfall)", "පුළුල් නිම්නය", "මෘදු තැනිතලාව", "කඳු කපොල්ල",
